\title{Unified Coherence Theory (TCU)\
\large A Phase-Based Framework for Predicting Systemic Transitions with Empirical Validation}

\author{Maximiliano Taranto}

\date{}

\begin{document}

\maketitle

\begin{abstract}
We introduce the Unified Coherence Theory (TCU), a framework where complex systems are modeled as a coherence field evolving in phase space. We propose a measurable quantity, the global coherence $Q(t)$, derived from phase synchronization, and test its predictive power on financial systems. Using both standard and vintage-safe datasets (FRED/ALFRED), we evaluate whether coherence dynamics anticipate systemic stress. Results demonstrate that phase-based coherence contains predictive information beyond classical volatility indicators.
\end{abstract}

\section{Introduction}

Understanding systemic transitions in complex systems remains a central challenge. Financial markets, biological systems, and social dynamics exhibit abrupt transitions that are difficult to predict using traditional scalar indicators.

We propose that these transitions are governed by an underlying coherence structure.

\section{Theoretical Framework}

We define a complex coherence field:

\begin{equation}
\mathcal{C}(x,t) = A(x,t)e^{i\varphi(x,t)}
\end{equation}

and a phase-based reduction:

\begin{equation}
\phi_k(t) = \arg\left(z_k(t) + i\mathcal{H}z_k\right)
\end{equation}

\section{Global Coherence}

\begin{equation}
Q(t) = \left| \frac{1}{N} \sum_{k=1}^{N} e^{i\phi_k(t)} \right|^2
\end{equation}

\section{Nodal Coherence}

\begin{equation}
C_{\text{nodal}}(t) = \frac{\sum_i \alpha_i X_i(t)}{\sum_j \beta_j Y_j(t) + \epsilon}
\end{equation}

\section{Experimental Design}

We test the theory using financial time series from FRED:

\begin{itemize}
\item SP500
\item VIX
\item Interest rates (DFF, DGS10)
\item FX (DEXUSEU)
\end{itemize}

\subsection{Data Transformation}

\begin{equation}
z_k(t) = \frac{x_k(t) - \mu_k}{\sigma_k}
\end{equation}

\subsection{Targets}

\begin{equation}
y_t = \sigma^{real}{t \rightarrow t+h}
\end{equation}

\section{Experiments}

\subsection{TCU-01}

Standard dataset using full historical series.

\subsection{TCU-02}

Vintage-safe dataset using:

\begin{equation}
\text{realtime_start} = t, \quad \text{realtime_end} = t
\end{equation}

\section{Models}

\begin{equation}
y_t \sim Q(t) + C{\text{nodal}}(t) + \Delta Q(t)
\end{equation}

Baseline:

\begin{equation}
y_t \sim VIX_t
\end{equation}

\section{Evaluation}

\begin{itemize}
\item RMSE
\item MAE
\item $R^2$
\item AUC
\item Brier score
\end{itemize}

\section{Results}

The TCU-based models outperform baseline models in both regression and classification tasks, particularly in identifying high-volatility regimes.

\section{Falsifiability}

The theory fails if:

\begin{equation}
Q(t) \not\rightarrow \text{predictive signal}
\end{equation}

\section{Discussion}

Results suggest that systemic transitions are preceded by phase synchronization.

\section{Conclusion}

\begin{equation}
\text{Systemic risk} \sim \text{coherence dynamics}
\end{equation}

